function coastline(grid: number[][]): number {
  const R = grid.length, C = grid[0].length;
  const seen = grid.map(row => row.map(() => false));
  const isLand = (y: number, x: number) => y >= 0 && y < R && x >= 0 && x < C && grid[y][x] === 1;
  let total = 0;
  for (let sy = 0; sy < R; sy++) for (let sx = 0; sx < C; sx++) {
    if (grid[sy][sx] !== 1 || seen[sy][sx]) continue;
    const stack = [[sy, sx]];
    seen[sy][sx] = true;
    while (stack.length) {
      const [y, x] = stack.pop()!;
      for (const [dy, dx] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
        const ny = y + dy, nx = x + dx;
        if (!isLand(ny, nx)) total++;
        else if (!seen[ny][nx]) { seen[ny][nx] = true; stack.push([ny, nx]); }
      }
    }
  }
  return total;
}

