class Solution:
    def coastline(self, grid: List[List[int]]) -> int:
        R, C = len(grid), len(grid[0])
        seen = [[False] * C for _ in range(R)]
        total = 0
        for sy in range(R):
            for sx in range(C):
                if grid[sy][sx] != 1 or seen[sy][sx]:
                    continue
                stack = [(sy, sx)]
                seen[sy][sx] = True
                while stack:
                    y, x = stack.pop()
                    for ny, nx in ((y + 1, x), (y - 1, x), (y, x + 1), (y, x - 1)):
                        if not (0 <= ny < R and 0 <= nx < C and grid[ny][nx] == 1):
                            total += 1
                        elif not seen[ny][nx]:
                            seen[ny][nx] = True
                            stack.append((ny, nx))
        return total

